import{z as E,x as i,o,c,q as t,j as s,D as a,d as n,s as d,S as l}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"宏与卫生","description":"","frontmatter":{"title":"宏与卫生","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/macros-hygiene.md","filePath":"cs/macros-hygiene.md","lastUpdated":1791413859000}'),p={name:"cs/macros-hygiene.md"};function A(B,e,m,h,_,u){const r=i("Mermaid");return o(),c("div",null,[e[2]||(e[2]=t('<h1 id="宏与卫生" tabindex="-1">宏与卫生 <a class="header-anchor" href="#宏与卫生" aria-label="Permalink to &quot;宏与卫生&quot;">​</a></h1><div class="epigraph"><p>宏是编译期的树或记号改写。不卫生的展开会捕获用户的名字；卫生宏用颜色或换名保证绑定结构不被偷偷改写。</p><footer>—— 据 Kohlbecker, Friedman, Felleisen and Duba, Hygienic Macro Expansion, 1986；Clinger and Rees, Macros That Work, 1991 整理</footer></div><p>上一课<a href="/cs/syntax-directed-translation">语法制导翻译</a>假定记号流已是语言本身。缺口是<strong>用户可定义的改写</strong>：Scheme 的 <code>syntax-rules</code>、Rust 的 <code>macro_rules</code>、模板元编程的边缘。本课钉捕获与卫生，不把 C 预处理器的全部坑写完——那是下一课。也不重写 λ 的 α 换名，只引用：<a href="/cs/lambda-calculus">λ 演算</a>里捕获会绑错，宏展开是同一事故的编译期版。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>非卫生：宏体里的 <code>tmp</code> 若与调用处的 <code>tmp</code> 同名，展开后绑到用户变量。卫生：宏引入的绑定带「颜色」，与用户标识符即使字符串相同也不冲突；用户传入的表达式在展开后仍绑到用户的环境。缺口是<strong>展开算法的换名不变量</strong>，不是再讲 SDT 的 <code>emit</code>。</p><p><span class="marginnote">直觉类比：不卫生展开像合租时两间房各配了一把都叫「备用钥匙」的钥匙——宏体里的 <code>tmp</code> 与用户的 <code>tmp</code> 字符串相同，展开后就可能插进用户的锁。卫生宏给每把钥匙发唯一编号（着色/gensym），同名也开不了别人的门。</span></p><p>对比函数：函数调用有求值规则与作用域；宏先改写再分析。把宏当函数会漏掉二次扫描与卫生。</p><h3 id="卫生不是「不能写坏宏」" tabindex="-1">卫生不是「不能写坏宏」 <a class="header-anchor" href="#卫生不是「不能写坏宏」" aria-label="Permalink to &quot;卫生不是「不能写坏宏」&quot;">​</a></h3><p>卫生防捕获；不防宏发出类型错误或指数大的代码。也不是卫生就不能故意 <code>unhygienic</code> 插入——部分语言提供逃逸，须显式。</p><p><span class="marginnote">Kohlbecker et al. 1986；Clinger–Rees 1991。Dybvig 的语法对象是工程标准参考。本课不进 typed template Haskell 的论文细节。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记号宏：替换列表，几乎必不卫生（C）。卫生宏：解析成语法对象，带词法上下文，展开时 <code>gensym</code> 或着色。模式匹配宏（<code>syntax-rules</code>）默认卫生；过程宏（<code>syntax-case</code>）要人遵守 API。</p>',12)),(o(),s(l,null,{default:a(()=>[d(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CALL%5B%22%E5%AE%8F%E8%B0%83%E7%94%A8%22%5D%20--%3E%20EXP%5B%22%E5%B1%95%E5%BC%80%22%5D%0A%20%20EXP%20--%3E%20COL%5B%22%E7%9D%80%E8%89%B2%20%2F%20gensym%22%5D%0A%20%20COL%20--%3E%20RE%5B%22%E5%86%8D%E5%88%86%E6%9E%90%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t('<p>与增量解析：宏展开使「源区间」映射变复杂，错误信息要指向调用处而非只指向展开后。接<a href="/cs/parse-error-recovery">错误恢复</a> 的诊断契约。</p><p><span class="marginnote">数字实例：C 里 <code>#define SWAP(a,b) { int tmp = a; a = b; b = tmp; }</code> 遇上 <code>SWAP(x, tmp)</code> 就出事——宏内的 <code>tmp</code> 展开后与用户传入的 <code>tmp</code> 撞名，交换被静默破坏。这正是「记号替换几乎必不卫生」的活例。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>多次展开直到没有宏调用（或达上限）。递归宏须终止；语言用进度检查或深度帽。卫生保证的是绑定结构，不保证与手工 α 换名后的项在类型上一律等价——那要另外的宏类型系统，本课点名。</p>',4)),(o(),s(l,null,{default:a(()=>[d(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%BA%90%E7%A8%8B%E5%BA%8F%E5%90%AB%E5%AE%8F%E8%B0%83%E7%94%A8%22%5D%20--%3E%20EXP%5B%22%E5%B1%95%E5%BC%80%E4%B8%80%E8%BD%AE%E6%94%B9%E5%86%99%22%5D%0A%20%20EXP%20--%3E%20HAS%7B%22%E4%BB%8D%E5%90%AB%E5%AE%8F%E8%B0%83%E7%94%A8%3F%22%7D%0A%20%20HAS%20--%3E%7C%22%E6%98%AF%22%7C%20EXP%0A%20%20HAS%20--%3E%7C%22%E5%90%A6%22%7C%20DONE%5B%22%E4%BA%A4%E7%BB%99%E7%BC%96%E8%AF%91%E5%99%A8%E5%90%8E%E7%AB%AF%22%5D%0A%20%20EXP%20--%3E%20CAP%7B%22%E6%B7%B1%E5%BA%A6%E5%B8%BD%20%2F%20%E8%BF%9B%E5%BA%A6%E6%A3%80%E6%9F%A5%22%7D%0A%20%20CAP%20--%3E%7C%22%E8%B6%85%E9%99%90%22%7C%20ERR%5B%22%E6%8B%92%E7%BB%9D%E7%BC%96%E8%AF%91%3A%20%E7%96%91%E4%BC%BC%E4%B8%8D%E7%BB%88%E6%AD%A2%E7%9A%84%E9%80%92%E5%BD%92%E5%AE%8F%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=t('<p><span class="marginnote">常见误区：初学者容易以为「卫生宏 = 安全的宏」。卫生只防名字捕获这一类事故，防不住展开出指数级代码、类型错误或不终止的递归——后者靠深度帽与进度检查在编译期硬性拦截。也别把卫生当成隐私：它保住的是绑定结构，不是封装。</span></p><p>不要用宏模拟模块系统的全部封装；卫生不是隐私。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 C 的 <code>#define</code> 扫描器。后课默认：卫生宏 = 展开不捕获；记号粘贴是另一家族。下一课 C 预处理器：故意不卫生、在词法阶段工作。</p><p>也不把 Rust 过程宏的编译器插件安全模型写完。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>宏是改写；捕获是 α 事故。</li><li>卫生用颜色或换名保住绑定。</li><li>记号宏（C）默认不卫生。</li><li>出处：Kohlbecker et al., 1986；Clinger and Rees, 1991。</li></ul>',7))])}const f=E(p,[["render",A]]);export{D as __pageData,f as default};
